const [command, ...args] = process.argv.slice(2);
if (!command) throw new Error("usage: recording-agent.mjs command [args...]");
const captureDir = process.env.ACP_CAPTURE_DIR;
if (!captureDir) throw new Error("ACP_CAPTURE_DIR is required");
fs.mkdirSync(captureDir, { recursive: true });
const child = spawn(command, args, { stdio: ["pipe", "pipe", "inherit"], env: process.env });
let seq = 0;
function record(direction, buffer) {
  let pending = Buffer.alloc(0);
  return (chunk) => {
    pending = Buffer.concat([pending, chunk]);
    for (;;) {
      const at = pending.indexOf(10);
      if (at < 0) break;
      const line = pending.subarray(0, at + 1);
      pending = pending.subarray(at + 1);
      const raw = line.toString("utf8").trim();
      try {
        const message = JSON.parse(raw);
        fs.appendFileSync(path.join(captureDir, "transcript.jsonl"), JSON.stringify({ sequence: ++seq, direction, message }) + "\\n");
      } catch {
        fs.appendFileSync(path.join(captureDir, "non-protocol.log"), raw + "\\n");
      }
    }
    buffer.write(chunk);
  };
}
