import os
import sys
import time

from Xlib import X, XK, display
from Xlib.ext import xtest

dpy = display.Display(os.environ["DISPLAY"])
root = dpy.screen().root

def top_windows():
    for child in root.query_tree().children:
        try:
            name = child.get_wm_name() or ""
            if name and ("Zed" in name or "zed" in name):
                yield child, name
        except Exception:
            pass

def focus_zed():
    for _ in range(60):
        matches = list(top_windows())
        if matches:
            win, name = matches[-1]
            win.configure(stack_mode=X.Above)
            win.set_input_focus(X.RevertToParent, X.CurrentTime)
            dpy.sync()
            time.sleep(0.5)
            print(name)
            return
        time.sleep(0.25)
    raise SystemExit("Zed window was not found")

def key(name, down=True):
    sym = XK.string_to_keysym(name)
    if not sym:
        raise SystemExit(f"unknown key symbol: {name}")
    code = dpy.keysym_to_keycode(sym)
    xtest.fake_input(dpy, X.KeyPress if down else X.KeyRelease, code)

def tap(name):
    key(name, True)
    dpy.sync()
    time.sleep(0.05)
    key(name, False)
    dpy.sync()
    time.sleep(0.05)

def type_ascii(value):
    for ch in value:
        if ch == " ":
            tap("space")
            continue
        if ch.isupper():
            key("Shift_L", True)
            tap(ch.lower())
            key("Shift_L", False)
        elif ch == "-":
            tap("minus")
        elif ch == "_":
            key("Shift_L", True)
            tap("minus")
            key("Shift_L", False)
        elif ch.isalnum():
            tap(ch)
        else:
            raise SystemExit(f"unsupported character: {ch!r}")
    dpy.sync()

if len(sys.argv) < 2:
    raise SystemExit("usage: zed_input.py focus|key <key>|chord <mod>... <key>|type <ascii text>")
mode = sys.argv[1]
if mode == "focus":
    focus_zed()
elif mode == "key" and len(sys.argv) == 3:
    focus_zed()
    tap(sys.argv[2])
elif mode == "chord" and len(sys.argv) >= 4:
    focus_zed()
    mods = sys.argv[2:-1]
    last = sys.argv[-1]
    for mod in mods:
        key(mod + "_L", True)
    tap(last)
    for mod in reversed(mods):
        key(mod + "_L", False)
    dpy.sync()
elif mode == "type" and len(sys.argv) == 3:
    focus_zed()
    type_ascii(sys.argv[2])
else:
    raise SystemExit("invalid arguments")
EOF
