+
+function signalProcessTree(child: ChildProcess, signal: NodeJS.Signals): void {
+  if (process.platform !== "win32" && child.pid !== undefined) {
+    try {
+      process.kill(-child.pid, signal);
+      return;
+    } catch (error) {
+      if ((error as NodeJS.ErrnoException).code !== "ESRCH") child.kill(signal);
+      return;
+    }
+  }
+  child.kill(signal);
+}
+
+/** Run a verifier in its own process group so cancellation and deadlines stop its shell descendants too. */
+export function runProbeProcess(
+  file: string,
+  args: string[],
+  options: { cwd: string; timeoutMs: number; signal?: AbortSignal; env?: NodeJS.ProcessEnv; dockerContainerName?: string },
+): Promise<ProbeProcessResult> {
+  if (options.signal?.aborted) {
+    return Promise.resolve({ status: null, signal: null, timedOut: false, cancelled: true });
+  }
+
+  return new Promise((resolve) => {
+    let child: ChildProcess;
+    try {
+      child = spawn(file, args, {
+        cwd: options.cwd,
+        detached: process.platform !== "win32",
+        env: options.env ?? scrubProbeEnv(),
+        stdio: "ignore",
+      });
+    } catch (error) {
+      resolve({ status: null, signal: null, error: error instanceof Error ? error.message : String(error), timedOut: false, cancelled: false });
+      return;
+    }
+
+    let termination: "timeout" | "cancelled" | undefined;
+    let killTimer: NodeJS.Timeout | undefined;
+    let settled = false;
+    const timer = setTimeout(() => terminate("timeout"), Math.max(1, options.timeoutMs));
+    timer.unref?.();
