+    const terminate = (reason: "timeout" | "cancelled") => {
+      if (termination || settled) return;
+      termination = reason;
+      signalProcessTree(child, "SIGTERM");
+      killTimer = setTimeout(() => signalProcessTree(child, "SIGKILL"), KILL_GRACE_MS);
+      killTimer.unref?.();
